const CONFIG_KEY='pharmaplus_supabase_config_v7';let sb=null,currentUser=null,profile=null,pharmacy=null,products=[],sales=[],saleItems=[],purchases=[],expenses=[],stockHistory=[],settings={name:'PharmaPlus Pharmacy',currency:'USh',location:'',contact:'',email:'',logo_url:''},saleCart=[],lastReceipt=null,currentProductId='',saleFilter='all',currentReport={cat:null,key:null,rows:[],title:''},onlineOrders=[],onlineFilter='all',onlineChannel=null,notificationItems=[],notificationCount=0,onlineOrderItemsCache=[];
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function cfg(){const u=window.PHARMAPLUS_SUPABASE_URL,k=window.PHARMAPLUS_SUPABASE_KEY;if(u&&k&&!u.includes('PASTE_YOUR_')&&!k.includes('PASTE_YOUR_'))return{url:u.trim(),key:k.trim()};try{return JSON.parse(localStorage.getItem(CONFIG_KEY)||localStorage.getItem('pharmaplus_supabase_config_v5')||'null')}catch{return null}}
function money(n){return `${settings.currency||'USh'} ${Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2})}`}
function standardTime(v){try{return new Intl.DateTimeFormat('en-UG',{dateStyle:'medium',timeStyle:'short',hour12:false,timeZone:'Africa/Kampala'}).format(new Date(v))}catch{return new Date(v).toLocaleString()}}
function notifyUser(title,body,kind='info'){const item={title,body,time:new Date(),kind};notificationItems.unshift(item);notificationItems=notificationItems.slice(0,30);notificationCount++;renderNotifications();document.title=`(${notificationCount}) PharmaPlus`;try{if('Notification' in window&&Notification.permission==='granted'&&document.hidden)new Notification(title,{body,tag:'pharmaplus-'+kind})}catch(e){}try{const C=window.AudioContext||window.webkitAudioContext;if(C){const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=kind==='order'?880:660;g.gain.value=.04;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.18)}}catch(e){}}
function renderNotifications(){const b=$('notifyBadge');if(b){b.textContent=notificationCount;b.classList.toggle('hidden',notificationCount<1)}const list=$('notificationList');if(list)list.innerHTML=notificationItems.length?notificationItems.map(n=>`<div class="notificationItem"><b>${esc(n.title)}</b><div>${esc(n.body)}</div><small>${standardTime(n.time)}</small></div>`).join(''):'<div class="empty">No notifications.</div>'}
function toggleNotifications(){const p=$('notificationPanel');if(!p)return;p.classList.toggle('hidden');if(!p.classList.contains('hidden')){notificationCount=0;document.title='PharmaPlus';renderNotifications()}}
async function enableNotifications(){try{if('Notification' in window&&Notification.permission==='default')await Notification.requestPermission()}catch(e){}}
function days(exp){return Math.ceil((new Date(exp+'T23:59:59')-new Date())/86400000)}function dateOnly(v){return v?String(v).slice(0,10):''}function drugLabel(p){return `${p.name}${p.brand_name?' ('+p.brand_name+')':''}`}function status(p){const d=days(p.expiry);if(d<0)return['Expired','bad'];if(Number(p.qty)<=0)return['Out of stock','bad'];if(d<=90)return['Expiring soon','warn'];if(Number(p.qty)<=10)return['Low stock','warn'];return['In stock','ok']}
function showMsg(t,type='error'){const m=$('authMessage');m.textContent=t;m.className='message '+type}function clearMsg(){$('authMessage').className='message hidden'}function showAuth(m){clearMsg();$('loginForm').classList.toggle('hidden',m!=='login');$('signupForm').classList.toggle('hidden',m!=='signup');$('tabLogin').classList.toggle('active',m==='login');$('tabSignup').classList.toggle('active',m==='signup')}
function openModal(id){$(id).classList.add('show');if(id==='configModal'){const c=cfg();$('cfgUrl').value=c?.url||'';$('cfgKey').value=c?.key||''}}function closeModal(id){$(id).classList.remove('show')}function toggleSidebar(){$('sidebar').classList.toggle('open')}document.querySelectorAll('.nav[data-page]').forEach(btn=>btn.addEventListener('click',()=>go(btn.dataset.page)));function go(page){document.querySelectorAll('.section').forEach(x=>x.classList.toggle('active',x.id===page));document.querySelectorAll('.nav[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('sidebar').classList.remove('open')}
document.getElementById('signOutBtn')?.addEventListener('click',signOut);
function applyPermissions(){const role=profile?.role||'staff';document.querySelectorAll('[data-roles]').forEach(el=>el.classList.toggle('hidden',!el.dataset.roles.split(',').includes(role)))}
async function connect(){const c=cfg();if(!c?.url||!c?.key){openModal('configModal');return false}try{sb=window.supabase.createClient(c.url,c.key);return true}catch(e){showMsg('Invalid Supabase configuration.');return false}}
$('configForm').onsubmit=async e=>{e.preventDefault();const url=$('cfgUrl').value.trim(),key=$('cfgKey').value.trim(),st=$('configStatus');try{const u=new URL(url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.pathname!=='/'||u.search||u.hash)throw Error('Invalid Project URL. Copy it exactly from Supabase Project Settings → API.');await fetch(url+'/auth/v1/settings',{headers:{apikey:key}});localStorage.setItem(CONFIG_KEY,JSON.stringify({url,key}));st.textContent='Connected. Reloading…';st.classList.remove('hidden');setTimeout(()=>location.reload(),500)}catch(err){st.textContent=err.message||'Could not connect';st.classList.remove('hidden')}};
$('loginForm').onsubmit=async e=>{e.preventDefault();if(!await connect())return;const {error}=await sb.auth.signInWithPassword({email:$('loginEmail').value.trim(),password:$('loginPassword').value});if(error)return showMsg(error.message);await boot()};$('signupForm').onsubmit=async e=>{e.preventDefault();if(!await connect())return;const invite=$('signupInvite').value.trim().toUpperCase();const meta={full_name:$('signupName').value.trim(),invite_code:invite,pharmacy_name:invite?'':$('signupPharmacy').value.trim(),pharmacy_location:invite?'':$('signupLocation').value.trim(),pharmacy_contact:invite?'':$('signupContact').value.trim()};if(!invite&&!meta.pharmacy_name)return showMsg('Enter the pharmacy name, or enter a valid staff invitation code.');const {data,error}=await sb.auth.signUp({email:$('signupEmail').value.trim(),password:$('signupPassword').value,options:{data:meta}});if(error)return showMsg(error.message);if(!data.session)showMsg('Account created. Check your email if email confirmation is enabled, then sign in.','ok');else await boot()};
async function forgotPassword(){const email=prompt('Enter your email address');if(!email||!await connect())return;const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin});showMsg(error?error.message:'Password reset email sent.','ok')}async function signOut(){if(!confirm('Are you sure you want to sign out?'))return;try{if(!sb){const ok=await connect();if(!ok)return}const {error}=await sb.auth.signOut({scope:'local'});if(error){alert('Could not sign out: '+error.message);return}currentUser=null;profile=null;pharmacy=null;location.replace(location.href.split('#')[0].split('?')[0]);}catch(err){alert('Could not sign out: '+(err?.message||err));}}
async function boot(){if(!await connect())return;const {data:{session}}=await sb.auth.getSession();if(!session){$('app').classList.add('hidden');$('auth').classList.remove('hidden');return}currentUser=session.user;let r=await sb.from('profiles').select('*').eq('id',currentUser.id).single();if(r.error||!r.data){showMsg('Your account is authenticated, but its staff profile is not ready. Run the latest supabase_schema.sql in Supabase SQL Editor.');return}profile=r.data;if(!profile.pharmacy_id){showMsg('Your staff profile has no pharmacy. Run the latest supabase_schema.sql again.');return}let pr=await sb.from('pharmacies').select('*').eq('id',profile.pharmacy_id).single();if(pr.error||!pr.data){showMsg('Pharmacy profile not found. Run the latest supabase_schema.sql.');return}pharmacy=pr.data;settings={...settings,...pharmacy};$('auth').classList.add('hidden');$('app').classList.remove('hidden');applyPermissions();renderProfile();enableNotifications();await loadData();if(!pharmacy.name||pharmacy.name==='PharmaPlus Pharmacy')setTimeout(()=>go('settings'),300)}
async function loadData(){
  if(!sb||!profile?.pharmacy_id){alert('Your session or pharmacy is not ready. Please sign in again.');return false}
  const pid=profile.pharmacy_id;
  const jobs={
    products: sb.from('products').select('*').eq('pharmacy_id',pid).order('created_at',{ascending:false}),
    sales: sb.from('sales').select('*').eq('pharmacy_id',pid).order('created_at',{ascending:false}),
    saleItems: sb.from('sale_items').select('*').eq('pharmacy_id',pid).order('created_at',{ascending:false}),
    purchases: sb.from('purchases').select('*').eq('pharmacy_id',pid).order('purchase_date',{ascending:false}),
    stockHistory: sb.from('product_stock_history').select('*').eq('pharmacy_id',pid).order('created_at',{ascending:false})
  };
  if(['admin','manager'].includes(profile.role)){
    jobs.expenses=sb.from('expenses').select('*').eq('pharmacy_id',pid).order('expense_date',{ascending:false}).order('created_at',{ascending:false});
  }
  const results=await Promise.all(Object.entries(jobs).map(async([key,p])=>[key,await p]));
  const failed=[];
  for(const [key,r] of results){
    if(r.error){failed.push(key+': '+r.error.message);continue}
    if(key==='products')products=r.data||[];
    if(key==='sales')sales=r.data||[];
    if(key==='saleItems')saleItems=r.data||[];
    if(key==='purchases')purchases=r.data||[];
    if(key==='stockHistory')stockHistory=r.data||[];
    if(key==='expenses')expenses=r.data||[];
  }
  // Optional-table errors must never hide existing medicines, POS or reports.
  if(failed.length) console.warn('PharmaPlus data warnings:',failed);
  renderAll();
  if(typeof loadOnlineOrders==='function'){await loadOnlineOrders(false);startOnlineOrdersRealtime();}
  const productFailure=failed.find(x=>x.startsWith('products:'));
  if(productFailure){alert('Inventory could not be loaded: '+productFailure.slice(9));return false}
  return true;
}
function renderProfile(){const n=pharmacy?.name||'PharmaPlus';$('sideName').textContent=n;$('topPharmacy').textContent=n;$('topUser').textContent=currentUser.email+' • '+profile.role;$('dashSub').textContent=`${pharmacy.location||''}${pharmacy.location&&pharmacy.contact?' • ':''}${pharmacy.contact||''}`;const av=$('avatar'),lg=$('sideLogo');if(pharmacy.logo_url){av.innerHTML=`<img src="${esc(pharmacy.logo_url)}">`;lg.innerHTML=`<img src="${esc(pharmacy.logo_url)}">`}else{av.textContent=(currentUser.email||'U')[0].toUpperCase();lg.textContent='✚'}$('setName').value=pharmacy.name||'';$('setContact').value=pharmacy.contact||'';$('setLocation').value=pharmacy.location||'';$('setEmail').value=pharmacy.email||'';$('setCurrency').value=pharmacy.currency||'USh';$('setMtnNumber').value=pharmacy.mtn_number||'';$('setMtnCode').value=pharmacy.mtn_merchant_code||'';$('setMtnName').value=pharmacy.mtn_registration_name||'';$('setAirtelNumber').value=pharmacy.airtel_number||'';$('setAirtelCode').value=pharmacy.airtel_merchant_code||'';$('setAirtelName').value=pharmacy.airtel_registration_name||'';$('setPickupLat').value=pharmacy.pickup_latitude??'';$('setPickupLng').value=pharmacy.pickup_longitude??'';$('setDeliveryFee').value=pharmacy.delivery_fee_per_km??0;$('logoPreview').innerHTML=pharmacy.logo_url?`<img src="${esc(pharmacy.logo_url)}">`:'No logo';renderNotifications()}
async function loadOnlineOrders(showErrors=false){if(!sb||!profile?.pharmacy_id)return false;const r=await sb.from('online_orders').select('*').eq('pharmacy_id',profile.pharmacy_id).order('created_at',{ascending:false});if(r.error){console.error(r.error);if(showErrors)alert('Online orders could not be loaded: '+r.error.message);return false}onlineOrders=r.data||[];const ir=await sb.from('online_order_items').select('*').eq('pharmacy_id',profile.pharmacy_id);onlineOrderItemsCache=ir.data||[];renderOnlineOrders();renderReportsBase();return true}
function setOnlineFilter(f,btn){onlineFilter=f;document.querySelectorAll('[data-online-filter]').forEach(x=>x.classList.remove('active'));btn?.classList.add('active');renderOnlineOrders()}
async function openOnlineOrder(id){const o=onlineOrders.find(x=>x.id===id);if(!o)return;const items=onlineOrderItemsCache.filter(x=>x.order_id===id);const map=o.latitude&&o.longitude?`https://www.google.com/maps?q=${o.latitude},${o.longitude}`:'';const qr=map?`<div><iframe class="mapFrame" src="https://www.google.com/maps?q=${o.latitude},${o.longitude}&output=embed" loading="lazy"></iframe><div class="qrBox"><b>Customer delivery location</b><br><img src="https://quickchart.io/qr?text=${encodeURIComponent(map)}&size=180" alt="Delivery location QR"><div class="mini">Scan with a phone camera to open Google Maps.</div><a href="${esc(map)}" target="_blank" rel="noopener">Open location</a></div></div>`:'<div class="note">Pickup order — no customer delivery location required.</div>';$('modalTitle').textContent=`Order ${o.order_number}`;$('modalBody').innerHTML=`<div class="onlineDetails"><div><div class="detailGrid"><div class="detailItem"><small>Customer</small><b>${esc(o.customer_name||'Customer')}</b></div><div class="detailItem"><small>Phone</small><b>${esc(o.phone||'—')}</b></div><div class="detailItem"><small>Customer type</small><b>${esc(o.customer_type||'retail')}</b></div><div class="detailItem"><small>Fulfillment</small><b>${esc(o.fulfillment)}</b></div><div class="detailItem"><small>Ordered</small><b>${standardTime(o.created_at)}</b></div><div class="detailItem"><small>Status</small><b>${esc(o.status)}</b></div></div><h3>Items (${items.length})</h3><div class="tableWrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.product_name)}${i.brand_name?`<div class="mini">${esc(i.brand_name)}</div>`:''}</td><td>${i.qty}</td><td>${money(i.unit_price)}</td><td>${money(i.line_total)}</td></tr>`).join('')}</tbody></table></div><div class="saleTotal"><span>Items total: ${money(Number(o.total)-Number(o.delivery_fee||0))}</span><span>Delivery: ${money(o.delivery_fee||0)}</span><span>Total: ${money(o.total)}</span></div><p><b>Payment:</b> ${esc(o.payment_method||'—')}${o.mobile_network?` · ${esc(o.mobile_network)}`:''}<br><b>Transaction:</b> ${esc(o.transaction_message||'—')}</p>${o.rejection_reason?`<div class="note dangerNote"><b>Rejection reason:</b> ${esc(o.rejection_reason)}</div>`:''}</div>${qr}</div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn secondary" onclick="printOnlineOrder('${o.id}')">🖨 Print receipt</button>${o.status==='pending'?`<button class="btn primary" onclick="changeOnlineStatus('${o.id}','ready')">Mark Ready</button><button class="btn danger" onclick="changeOnlineStatus('${o.id}','rejected')">Reject</button>`:''}${o.status==='ready'?`<button class="btn blue" onclick="changeOnlineStatus('${o.id}','out_for_delivery')">Out for delivery</button>`:''}${o.status==='out_for_delivery'?`<button class="btn blue" onclick="changeOnlineStatus('${o.id}','delivered')">Mark Delivered</button>`:''}</div>`;openModal('orderDetailModal')}
async function changeOnlineStatus(id,status){if(status==='rejected'){const reason=prompt('Reason for rejecting this order:');if(!reason?.trim())return;const r=await sb.rpc('update_online_order_status',{p_order:id,p_status:'rejected',p_rejection_reason:reason.trim()});if(r.error)return alert(r.error.message);notifyUser('Online order rejected',reason.trim(),'order');await loadOnlineOrders();openOnlineOrder(id);return}if(!confirm(`Change this order to ${status.replaceAll('_',' ')}?`))return;const before=onlineOrders.find(o=>o.id===id);const r=await sb.rpc('update_online_order_status',{p_order:id,p_status:status,p_rejection_reason:null});if(r.error)return alert(r.error.message);notifyUser('Online order updated',`Order ${before?.order_number||''} is now ${status.replaceAll('_',' ')}`,'order');await loadOnlineOrders();if(status==='ready'){closeModal('orderDetailModal');setTimeout(()=>printOnlineOrder(id),250);return}openOnlineOrder(id)}
function renderOnlineOrders(){const pending=onlineOrders.filter(o=>o.status==='pending').length;const b=$('onlinePendingBadge');if(b){b.textContent=pending;b.classList.toggle('hidden',pending<1)}const nb=$('onlineNavBadge');if(nb){nb.textContent=pending;nb.classList.toggle('hidden',pending<1)}const arr=onlineOrders.filter(o=>onlineFilter==='all'||o.status===onlineFilter);const counts={};onlineOrders.forEach(o=>counts[o.status]=(counts[o.status]||0)+1);document.querySelectorAll('[data-online-filter]').forEach(x=>{if(x.dataset.onlineFilter==='pending')x.innerHTML=`Pending${counts.pending?` <span class="orderBadge">${counts.pending}</span>`:''}`});$('onlineOrderRows').innerHTML=arr.map(o=>{const itemCount=onlineOrderItemsCache.filter(i=>i.order_id===o.id).length;return `<tr onclick="openOnlineOrder('${o.id}')" style="cursor:pointer"><td><b>${esc(o.order_number)}</b><br><small>${standardTime(o.created_at)}</small></td><td><b>${esc(o.customer_name||'Customer')}</b></td><td>${esc(o.phone||'')}</td><td>${itemCount}</td><td>${esc(o.fulfillment)}</td><td>${money(o.total)}</td><td><span class="badge ${o.status==='confirmed'?'ok':o.status==='ready'||o.status==='delivered'?'info':o.status==='rejected'||o.status==='cancelled'?'bad':'warn'}">${esc(o.status.replaceAll('_',' '))}</span></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No online orders.</td></tr>'}
function printOnlineOrder(id){
 const o=onlineOrders.find(x=>x.id===id); if(!o)return;
 const items=onlineOrderItemsCache.filter(x=>x.order_id===id);
 const map=o.latitude!=null&&o.longitude!=null?`https://www.google.com/maps?q=${o.latitude},${o.longitude}`:'';
 const qr=map?`<div class="receiptQR"><img src="https://quickchart.io/qr?text=${encodeURIComponent(map)}&size=220" width="170" height="170"><b>Customer delivery location</b><div>Scan QR code to open location in Google Maps</div></div>`:'';
 const itemsTotal=items.reduce((a,i)=>a+Number(i.line_total||0),0);
 const w=window.open('','_blank'); if(!w)return alert('Allow pop-ups to print the receipt.');
 w.document.write(`<html><head><title>Online Order ${esc(o.order_number)}</title><style>@page{size:auto;margin:10mm}body{font-family:Arial,sans-serif;background:#fff;color:#111;padding:20px;max-width:420px;margin:auto;font-size:12px}.receipt{border:1px solid #ddd;padding:18px}.center{text-align:center}.meta{text-align:center;font-size:11px;color:#555;line-height:1.55}.title{font-size:18px;font-weight:800;margin:5px 0}.customer{margin:12px 0;padding:9px;border:1px solid #ddd;border-radius:6px}.customer b{display:block}.receiptTable{width:100%;border-collapse:collapse;margin-top:12px}.receiptTable th,.receiptTable td{padding:7px 4px;border-bottom:1px dashed #ccc;text-align:left;font-size:11px}.receiptTable th:last-child,.receiptTable td:last-child{text-align:right}.totals{border-top:1px dashed #777;margin-top:8px;padding-top:8px;text-align:right;line-height:1.8}.grand{font-size:16px;font-weight:800}.receiptQR{text-align:center;border-top:1px dashed #777;margin-top:14px;padding-top:14px}.receiptQR img{display:block;margin:0 auto 7px}.receiptQR div{font-size:10px;color:#555;margin-top:3px}.note{font-size:10px;text-align:center;color:#666;margin-top:12px;font-style:italic}</style></head><body><div class="receipt"><div class="center">${pharmacy.logo_url?`<img src="${esc(pharmacy.logo_url)}" style="width:65px;height:65px;object-fit:contain">`:''}<div class="title">${esc(pharmacy.name)}</div></div><div class="meta">${esc(pharmacy.location||'')}${pharmacy.contact?`<br>${esc(pharmacy.contact)}`:''}${pharmacy.email?`<br>${esc(pharmacy.email)}`:''}<br><b>ONLINE ORDER RECEIPT</b><br>Order: ${esc(o.order_number)}<br>${standardTime(o.created_at)}</div><div class="customer"><b>Customer: ${esc(o.customer_name||'Customer')}</b>Phone: ${esc(o.phone||'—')}<br>Type: ${esc(o.customer_type||'retail')}<br>Fulfillment: ${esc(o.fulfillment||'—')}${o.delivery_address?`<br>Address: ${esc(o.delivery_address)}`:''}</div><table class="receiptTable"><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.product_name)}${i.brand_name?`<br><small>${esc(i.brand_name)}</small>`:''}</td><td>${i.qty}</td><td>${money(i.unit_price)}</td><td>${money(i.line_total)}</td></tr>`).join('')}</tbody></table><div class="totals">Items total: ${money(itemsTotal)}<br>Delivery fee: ${money(o.delivery_fee||0)}<br><span class="grand">TOTAL: ${money(o.total)}</span></div>${qr}<div class="meta" style="margin-top:12px">Payment: ${esc(o.payment_method||'—')}${o.mobile_network?` · ${esc(o.mobile_network)}`:''}<br>Transaction: ${esc(o.transaction_message||'—')}<br>Status: ${esc(o.status||'')}</div><div class="note">goods once sold are not returnable</div></div><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close();
}
function startOnlineOrdersRealtime(){if(!sb||!profile?.pharmacy_id)return;if(onlineChannel){try{sb.removeChannel(onlineChannel)}catch(e){}}onlineChannel=sb.channel('pharmaplus-online-orders-'+profile.pharmacy_id).on('postgres_changes',{event:'*',schema:'public',table:'online_orders',filter:'pharmacy_id=eq.'+profile.pharmacy_id},payload=>{if(payload.eventType==='INSERT')notifyUser('New online order',`Order ${payload.new?.order_number||''} from ${payload.new?.customer_name||'Customer'}`,'order');else if(payload.eventType==='UPDATE')notifyUser('Online order updated',`Order ${payload.new?.order_number||''} is now ${payload.new?.status||''}`,'order');loadOnlineOrders(false)}).subscribe()}
function renderAll(){renderDashboard();renderSales();renderInventory();renderPurchases();renderReportsBase();renderExpenses();renderStaff();applyPermissions()}
function renderDashboard(){const t=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Kampala'}).format(new Date()),tod=sales.filter(s=>s.status==='completed'&&dateOnly(s.created_at)===t);$('dSales').textContent=money(tod.reduce((a,s)=>a+Number(s.total),0));$('dProfit').textContent=money(tod.reduce((a,s)=>a+Number(s.profit),0));$('dStock').textContent=money(products.filter(p=>!p.archived).reduce((a,p)=>a+Number(p.qty)*Number(p.buy),0));$('dLow').textContent=products.filter(p=>!p.archived&&Number(p.qty)<=10&&Number(p.qty)>0&&days(p.expiry)>=0).length;$('dExp').textContent=products.filter(p=>!p.archived&&days(p.expiry)>=0&&days(p.expiry)<=90).length;$('lowRows').innerHTML=products.filter(p=>!p.archived&&Number(p.qty)<=10&&Number(p.qty)>0&&days(p.expiry)>=0).slice(0,8).map(p=>`<tr><td>${esc(drugLabel(p))}</td><td>${p.qty}</td><td>10</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No low-stock medicines.</td></tr>';$('expRows').innerHTML=products.filter(p=>!p.archived&&days(p.expiry)>=0&&days(p.expiry)<=90).slice(0,8).map(p=>`<tr><td>${esc(drugLabel(p))}</td><td>${esc(p.batch)}</td><td>${p.expiry}</td><td>${days(p.expiry)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No medicines expiring soon.</td></tr>';const now=new Date(),labels=[],vals=[];for(let i=6;i>=0;i--){const d=new Date(now);d.setDate(d.getDate()-i);const k=d.toISOString().slice(0,10);labels.push(k.slice(5));vals.push(sales.filter(s=>s.status==='completed'&&dateOnly(s.created_at)===k).reduce((a,s)=>a+Number(s.total),0))}const mx=Math.max(...vals,1);$('chart').innerHTML=vals.map((v,i)=>`<div class="bar" style="height:${Math.max(12,v/mx*160)}px"><span>${labels[i]}</span></div>`).join('');const map={};saleItems.filter(i=>sales.find(s=>s.id===i.sale_id)?.status==='completed').forEach(x=>{const k=drugLabel({name:x.product_name,brand_name:x.brand_name});map[k]=(map[k]||0)+Number(x.qty)});$('topList').innerHTML=Object.entries(map).sort((a,b)=>b[1]-a[1]).slice(0,7).map((x,i)=>`<div style="display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--line)"><span>${i+1}. ${esc(x[0])}</span><b>${x[1]}</b></div>`).join('')||'<div class="empty">No completed sales yet.</div>';$('accountCard').innerHTML=`<div><b>${esc(pharmacy.name)}</b></div><div class="mini">${esc(pharmacy.location||'Location not set')}</div><div class="mini">${esc(pharmacy.contact||'Contact not set')}</div><div class="mini" style="margin-top:8px">Signed in as ${esc(currentUser.email)}</div>`}
function setSaleFilter(f,btn){saleFilter=f;document.querySelectorAll('[data-sale-filter]').forEach(x=>x.classList.remove('active'));btn?.classList.add('active');renderSales()}
function renderSales(){const itemCount={};saleItems.forEach(i=>itemCount[i.sale_id]=(itemCount[i.sale_id]||0)+1);const arr=sales.filter(s=>saleFilter==='all'||s.status===saleFilter);$('salesRows').innerHTML=arr.map(s=>`<tr onclick="openSaleDetails('${s.id}')" style="cursor:pointer"><td>${standardTime(s.created_at)}</td><td><b>${esc(s.receipt)}</b></td><td>${s.sale_type==='wholesale'?`<span class="clickable" onclick="event.stopPropagation();showWholesale('${String(s.business_name||'').replace(/'/g,"\'")}')">${esc(s.business_name)}</span>`:'Walk-in'}</td><td>${itemCount[s.id]||0}</td><td>${money(s.total)}</td><td>${money(s.profit)}</td><td>${esc(s.payment||'')}</td><td><span class="badge ${s.status==='completed'?'ok':s.status==='rejected'?'bad':'warn'}">${esc(s.status)}</span></td><td onclick="event.stopPropagation()"><button class="btn blue" onclick="showStoredReceipt('${s.id}')">Receipt</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No sales in this view.</td></tr>'}
function openSaleDetails(id){const s=sales.find(x=>x.id===id);if(!s)return;const items=saleItems.filter(x=>x.sale_id===id);$('modalTitle').textContent=`Sale ${s.receipt}`;$('modalBody').innerHTML=`<div class="detailGrid"><div class="detailItem"><small>Date</small><b>${standardTime(s.created_at)}</b></div><div class="detailItem"><small>Customer</small><b>${esc(s.sale_type==='wholesale'?s.business_name:'Walk-in')}</b></div><div class="detailItem"><small>Items</small><b>${items.length}</b></div><div class="detailItem"><small>Payment</small><b>${esc(s.payment||'')}</b></div><div class="detailItem"><small>Status</small><b>${esc(s.status)}</b></div><div class="detailItem"><small>Total</small><b>${money(s.total)}</b></div></div><div class="tableWrap" style="margin-top:14px"><table><thead><tr><th>Item</th><th>Batch</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(drugLabel(i))}</td><td>${esc(i.batch||'')}</td><td>${i.qty}</td><td>${money(i.unit_sell)}</td><td>${money(i.line_total)}</td></tr>`).join('')}</tbody></table></div><div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn secondary" onclick="showStoredReceipt('${s.id}')">🧾 View / Print Receipt</button>${s.status==='pending'?`<button class="btn primary" onclick="completePendingSale('${s.id}')">Complete Sale</button><button class="btn danger" onclick="rejectPendingSale('${s.id}')">Reject Sale</button>`:''}</div>`;openModal('orderDetailModal')}

function renderInventory(){const f=$('invFilter')?.value||'all';let arr=[...products];if(f==='archived')arr=arr.filter(p=>p.archived);else{arr=arr.filter(p=>!p.archived);arr=arr.filter(p=>{const d=days(p.expiry);if(f==='low')return p.qty<=10&&p.qty>0&&d>=0;if(f==='expired')return d<0;if(f==='expiring')return d>=0&&d<=90;if(f==='in-stock')return p.qty>0&&d>=0;if(f==='out-stock')return p.qty<=0;return true})}$('invProducts').textContent=products.filter(p=>!p.archived).length;$('invUnits').textContent=products.filter(p=>!p.archived).reduce((a,p)=>a+Number(p.qty),0).toLocaleString();$('invValue').textContent=money(products.filter(p=>!p.archived).reduce((a,p)=>a+Number(p.qty)*Number(p.buy),0));$('invLow').textContent=products.filter(p=>!p.archived&&p.qty<=10&&p.qty>0&&days(p.expiry)>=0).length;$('invExp').textContent=products.filter(p=>!p.archived&&days(p.expiry)>=0&&days(p.expiry)<=90).length;$('invRows').innerHTML=arr.map(p=>{const st=status(p);return `<tr onclick="showProductDetails('${p.id}')" style="cursor:pointer"><td><b>${esc(drugLabel(p))}</b></td><td>${esc(p.category)}</td><td>${esc(p.batch)}</td><td>${p.expiry}</td><td>${p.qty}</td><td>${money(p.wholesale_price??p.sell)}</td><td>${money(p.retail_price??p.sell)}</td><td><span class="badge ${p.archived?'info':st[1]}">${p.archived?'Archived':st[0]}</span></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No medicines match.</td></tr>'}
function populateHistorySuggestions(){const uniq=a=>[...new Set(a.filter(Boolean).map(String))];$('genericHistory').innerHTML=uniq(products.map(p=>p.name)).map(v=>`<option value="${esc(v)}"></option>`).join('');$('brandHistory').innerHTML=uniq(products.map(p=>p.brand_name)).map(v=>`<option value="${esc(v)}"></option>`).join('');$('categoryHistory').innerHTML=uniq(products.map(p=>p.category)).map(v=>`<option value="${esc(v)}"></option>`).join('')}
function refreshHistoryMatches(){const q=$('productName').value.trim().toLowerCase();const matches=products.filter(p=>!p.archived&&(!q||p.name.toLowerCase().includes(q))).slice(0,20);$('genericHistory').innerHTML=matches.map(p=>`<option value="${esc(p.name)}"></option>`).join('')}
function openProductModal(id=''){populateHistorySuggestions();setTimeout(refreshHistoryMatches,0);const p=products.find(x=>x.id===id);$('productId').value=p?.id||'';$('productName').value=p?.name||'';$('productBrand').value=p?.brand_name||'';$('productCategory').value=p?.category||'';$('productBatch').value=p?.batch||'';$('productExpiry').value=p?.expiry||'';$('productQty').value=p?.qty??0;$('productBuy').value=p?.buy??0;$('productWholesale').value=p?.wholesale_price??p?.sell??0;$('productRetail').value=p?.retail_price??p?.sell??0;$('productEntered').value=dateOnly(p?.entered_date||p?.created_at)||new Date().toISOString().slice(0,10);$('productModalTitle').textContent=p?'Edit Medicine':'Add Medicine';const can=['admin','manager'].includes(profile?.role);$('productQty').disabled=!!p&&!can;$('productBuy').disabled=!!p&&!can;$('productWholesale').disabled=!!p&&!can;$('productRetail').disabled=!!p&&!can;updateMargin();openModal('productModal')}
function updateMargin(){const buy=Number($('productBuy').value),wh=Number($('productWholesale').value),ret=Number($('productRetail').value);$('productMargin').textContent=`Wholesale profit/unit: ${money(wh-buy)} • Retail profit/unit: ${money(ret-buy)}`}$('productBuy').oninput=updateMargin;$('productWholesale').oninput=updateMargin;$('productRetail').oninput=updateMargin;
function toggleDetailActions(btn){$('detailActionsPanel').classList.toggle('hidden')}
async function showProductDetails(id){const p=products.find(x=>x.id===id);if(!p)return;currentProductId=id;const hist=stockHistory.filter(x=>x.product_id===id),items=saleItems.filter(x=>x.product_id===id);$('detailsTitle').textContent=drugLabel(p);$('detailsContent').innerHTML=`<div class="detailGrid"><div class="detailItem"><small>Generic name</small><b>${esc(p.name)}</b></div><div class="detailItem"><small>Brand name</small><b>${esc(p.brand_name||'')}</b></div><div class="detailItem"><small>Category</small><b>${esc(p.category)}</b></div><div class="detailItem"><small>Batch</small><b>${esc(p.batch)}</b></div><div class="detailItem"><small>Expiry</small><b>${esc(p.expiry)}</b></div><div class="detailItem"><small>Date entered</small><b>${esc(dateOnly(p.entered_date||p.created_at))}</b></div><div class="detailItem"><small>Current quantity</small><b>${p.qty}</b></div><div class="detailItem"><small>Buying price</small><b>${money(p.buy)}</b></div><div class="detailItem"><small>Wholesale price</small><b>${money(p.wholesale_price??p.sell)}</b></div><div class="detailItem"><small>Retail price</small><b>${money(p.retail_price??p.sell)}</b></div></div><div class="card" style="margin-top:14px"><div class="cardHead"><h3>Stocking history</h3></div><div class="tableWrap"><table><thead><tr><th>Date</th><th>Change</th><th>Previous</th><th>New</th><th>Reason</th></tr></thead><tbody>${hist.map(h=>`<tr><td>${new Date(h.created_at).toLocaleString()}</td><td>${h.change_qty>0?'+':''}${h.change_qty}</td><td>${h.previous_qty}</td><td>${h.new_qty}</td><td>${esc(h.reason||'Stock adjustment')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No stocking history yet.</td></tr>'}</tbody></table></div></div><div class="card" style="margin-top:14px"><div class="cardHead"><h3>Sales history</h3></div><div class="tableWrap"><table><thead><tr><th>Date</th><th>Receipt</th><th>Brand</th><th>Batch</th><th>Qty</th><th>Total</th><th>Status</th></tr></thead><tbody>${items.map(i=>{const sl=sales.find(x=>x.id===i.sale_id);return `<tr><td>${sl?new Date(sl.created_at).toLocaleString():''}</td><td>${esc(sl?.receipt||'')}</td><td>${esc(i.brand_name||p.brand_name||'')}</td><td>${esc(i.batch||p.batch)}</td><td>${i.qty}</td><td>${money(i.line_total)}</td><td>${esc(sl?.status||'')}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No sales for this medicine yet.</td></tr>'}</tbody></table></div></div>`;const panel=$('detailActionsPanel');const can=['admin','manager'].includes(profile?.role);panel.innerHTML=`<button onclick="editFromDetails()">✏ Edit medicine (including quantity & prices)</button>${can?(p.archived?`<button onclick="restoreProduct('${p.id}')">↩ Restore medicine</button>`:`<button onclick="archiveProduct('${p.id}')">📦 Archive medicine</button>`):''}${can?`<button class="dangerText" onclick="deleteProduct('${p.id}')">🗑 Delete medicine</button>`:''}`;panel.classList.add('hidden');openModal('detailsModal')}
function editFromDetails(){closeModal('detailsModal');openProductModal(currentProductId)}
async function archiveProduct(id){if(!['admin','manager'].includes(profile?.role))return alert('Only Admin and Manager can archive medicines.');if(!confirm('Archive this medicine? It will no longer be available for new sales, but its history will be preserved.'))return;const r=await sb.from('products').update({archived:true}).eq('id',id).eq('pharmacy_id',profile.pharmacy_id);if(r.error)return alert(r.error.message);closeModal('detailsModal');await loadData()}
async function restoreProduct(id){if(!['admin','manager'].includes(profile?.role))return;if(!confirm('Restore this medicine to active inventory?'))return;const r=await sb.from('products').update({archived:false}).eq('id',id).eq('pharmacy_id',profile.pharmacy_id);if(r.error)return alert(r.error.message);closeModal('detailsModal');await loadData()}
async function deleteProduct(id){if(!['admin','manager'].includes(profile?.role))return;if(!confirm('Permanently delete this medicine? Historical sale records will be kept, but the medicine record itself will be removed.'))return;const r=await sb.from('products').delete().eq('id',id).eq('pharmacy_id',profile.pharmacy_id);if(r.error)return alert(r.error.message);closeModal('detailsModal');await loadData()}
function exportInventory(){const rows=[['Generic name','Brand','Category','Batch','Expiry','Date entered','Quantity','Buying Price','Wholesale Price','Retail Price','Archived'],...products.map(p=>[p.name,p.brand_name||'',p.category,p.batch,p.expiry,dateOnly(p.entered_date||p.created_at),p.qty,p.buy,p.wholesale_price??p.sell,p.retail_price??p.sell,p.archived?'Yes':'No'])];const ws=XLSX.utils.aoa_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Inventory');XLSX.writeFile(wb,'PharmaPlus-Inventory.xlsx')}
function openSaleModal(){saleCart=[];lastReceipt=null;$('saleType').value='walk_in';$('businessName').value='';$('businessWrap').classList.add('hidden');$('salePayment').value='Cash';addSaleItem();openModal('saleModal')}$('saleType').onchange=()=>{ $('businessWrap').classList.toggle('hidden',$('saleType').value!=='wholesale'); renderSaleCart(); };
function addSaleItem(pref){saleCart.push(pref||{productId:'',qty:1});renderSaleCart()}function removeSaleItem(i){saleCart.splice(i,1);renderSaleCart()}
function saleDrugOptionsHTML(){const active=products.filter(p=>!p.archived&&p.qty>0&&days(p.expiry)>=0);return active.map(p=>`<option value=\"${esc(drugLabel(p))} — Batch: ${esc(p.batch)} — Exp: ${esc(p.expiry)}\"></option>`).join('')}
function chooseSaleDrug(i,val){const active=products.filter(p=>!p.archived&&p.qty>0&&days(p.expiry)>=0);const p=active.find(x=>`${drugLabel(x)} — Batch: ${x.batch} — Exp: ${x.expiry}`===val);saleCart[i].productId=p?.id||'';renderSaleCart()}
function renderSaleCart(){const active=products.filter(p=>!p.archived&&p.qty>0&&days(p.expiry)>=0);$('saleItemsBody').innerHTML=saleCart.map((x,i)=>{const p=products.find(y=>y.id===x.productId);const price=p?($('saleType').value==='wholesale'?Number(p.wholesale_price??p.sell):Number(p.retail_price??p.sell)):0;const val=p?`${drugLabel(p)} — Batch: ${p.batch} — Exp: ${p.expiry}`:'';return `<tr><td><input list=\"saleDrugOptions${i}\" value=\"${esc(val)}\" placeholder=\"Enter item name\" oninput=\"chooseSaleDrug(${i},this.value)\" autocomplete=\"off\"><datalist id=\"saleDrugOptions${i}\">${active.map(p=>`<option value=\"${esc(drugLabel(p))} — Batch: ${esc(p.batch)} — Exp: ${esc(p.expiry)}\"></option>`).join('')}</datalist></td><td>${p?`${p.qty}<div class=\"mini\">Batch ${esc(p.batch)} • Exp ${esc(p.expiry)}</div>`:'—'}</td><td><input style=\"width:80px\" type=\"number\" min=\"1\" max=\"${p?.qty||1}\" value=\"${x.qty}\" onchange=\"saleCart[${i}].qty=+this.value;renderSaleCart()\"></td><td>${money(price)}</td><td>${money(price*x.qty)}</td><td><button type=\"button\" class=\"btn danger\" onclick=\"removeSaleItem(${i})\">×</button></td></tr>`}).join('');const total=saleCart.reduce((a,x)=>{const p=products.find(y=>y.id===x.productId);const price=p?($('saleType').value==='wholesale'?Number(p.wholesale_price??p.sell):Number(p.retail_price??p.sell)):0;return a+price*x.qty},0),profit=saleCart.reduce((a,x)=>{const p=products.find(y=>y.id===x.productId);const price=p?($('saleType').value==='wholesale'?Number(p.wholesale_price??p.sell):Number(p.retail_price??p.sell)):0;return a+(price-(p?Number(p.buy):0))*x.qty},0);$('saleGrandTotal').textContent=money(total);$('saleGrandProfit').textContent=money(profit)}
$('productName').addEventListener('input',()=>{refreshHistoryMatches();const q=$('productName').value.trim().toLowerCase();if(!q)return;const p=products.find(x=>!x.archived&&x.name.toLowerCase()===q);if(p&&!$('productId').value){$('productBrand').value=p.brand_name||'';$('productCategory').value=p.category||'';$('productBuy').value=p.buy??'';$('productWholesale').value=p.wholesale_price??p.sell??'';$('productRetail').value=p.retail_price??p.sell??'';updateMargin()}});
$('productForm').onsubmit=async e=>{e.preventDefault();if(!confirm($('productId').value?'Are you sure you want to save these medicine changes?':'Are you sure you want to add this medicine?'))return;const id=$('productId').value,can=['admin','manager'].includes(profile?.role),old=products.find(x=>x.id===id),ret=Number($('productRetail').value),row={name:$('productName').value.trim(),brand_name:$('productBrand').value.trim(),category:$('productCategory').value.trim(),batch:$('productBatch').value.trim(),expiry:$('productExpiry').value,qty:+$('productQty').value,buy:+$('productBuy').value,wholesale_price:+$('productWholesale').value,retail_price:ret,sell:ret,entered_date:$('productEntered').value||new Date().toISOString().slice(0,10),pharmacy_id:profile.pharmacy_id,created_by:currentUser.id};if(id&&!can&&(old.qty!==row.qty||Number(old.buy)!==Number(row.buy)||Number(old.wholesale_price??old.sell)!==row.wholesale_price||Number(old.retail_price??old.sell)!==row.retail_price))return alert('Only Admin and Manager can change medicine quantity or prices.');const r=id?await sb.from('products').update(row).eq('id',id).eq('pharmacy_id',profile.pharmacy_id):await sb.from('products').insert(row);if(r.error)return alert(r.error.message);closeModal('productModal');await loadData()}
function openSaleStatus(id){openSaleDetails(id)}
async function createPendingSale(){const t=saleTotals();const r=await sb.rpc('create_pending_sale',{p_sale_type:$('saleType').value,p_business_name:$('businessName').value.trim()||null,p_payment:$('salePayment').value,p_items:saleItemsPayload()});if(r.error)throw Error(r.error.message);return r.data?.[0]||r.data}
function receiptHTML(data,provisional=true){const items=data.items||[];return `<div class="receiptPreview" id="printReceiptArea">${pharmacy.logo_url?`<div style="text-align:center"><img src="${esc(pharmacy.logo_url)}" style="width:70px;height:70px;object-fit:contain"></div>`:''}<h2>${esc(pharmacy.name)}</h2><div class="receiptMeta">${esc(pharmacy.location||'')}${pharmacy.location&&pharmacy.contact?' • ':''}${esc(pharmacy.contact||'')}<br>${esc(pharmacy.email||'')}</div><h3>${provisional?'PROVISIONAL RECEIPT':'SALES RECEIPT'}</h3><div class="receiptMeta">Receipt: ${esc(data.receipt)}<br>${standardTime(data.date||Date.now())}<br>Customer: ${data.sale_type==='wholesale'?esc(data.business_name):'Walk-in'}</div><table class="receiptTable"><thead><tr><th>Item</th><th>Batch</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(drugLabel(i))}</td><td>${esc(i.batch||'')}</td><td>${i.qty}</td><td>${money(i.unit_sell)}</td><td>${money(i.line_total)}</td></tr>`).join('')}</tbody></table><div class="receiptTotal">TOTAL: ${money(data.total)}</div><div class="receiptMeta" style="margin-top:10px">Payment method: ${esc(data.payment||'')}</div><div class="mutedItalic" style="text-align:center;margin-top:12px">goods once sold are not returnable</div></div>`}
function saleItemsPayload(){return saleCart.map(x=>({product_id:x.productId,qty:Number(x.qty)}))}
async function previewReceipt(){try{if(lastReceipt?.id&&lastReceipt.status==='pending'){const items=saleItems.filter(x=>x.sale_id===lastReceipt.id);lastReceipt.items=items;$('receiptContent').innerHTML=receiptHTML(lastReceipt,true);showReceiptButtons(true);openModal('receiptModal');return}if(!confirm('Create this sale as a pending sale so the provisional receipt can be printed? Stock will not be deducted until the sale is completed.'))return;const saved=await createPendingSale();const items=saleCart.map(x=>{const p=products.find(y=>y.id===x.productId);const price=$('saleType').value==='wholesale'?Number(p.wholesale_price??p.sell):Number(p.retail_price??p.sell);return{product_name:p.name,brand_name:p.brand_name||'',batch:p.batch,qty:x.qty,unit_sell:price,line_total:price*x.qty}});lastReceipt={id:saved.sale_id,receipt:saved.receipt,sale_type:$('saleType').value,business_name:$('businessName').value.trim(),payment:$('salePayment').value,total:Number(saved.total),profit:Number(saved.profit),status:'pending',date:new Date(),items};await loadData();$('receiptContent').innerHTML=receiptHTML(lastReceipt,true);showReceiptButtons(true);closeModal('saleModal');openModal('receiptModal')}catch(e){alert(e.message)}}
function showReceiptButtons(pending){$('receiptCompleteBtn').classList.toggle('hidden',!pending);$('receiptRejectBtn').classList.toggle('hidden',!pending)}
async function completeCurrentSale(){if(lastReceipt?.id&&lastReceipt.status==='pending'){await completePendingSale(lastReceipt.id);return}closeModal('receiptModal')}
async function completePendingSale(id){if(!confirm('Complete this pending sale? Stock will now be deducted and revenue recorded.'))return;const r=await sb.rpc('complete_pending_sale',{p_sale_id:id});if(r.error)return alert(r.error.message);await loadData();const s=sales.find(x=>x.id===id),items=saleItems.filter(x=>x.sale_id===id);lastReceipt={...s,date:s?.created_at||new Date(),items};closeModal('orderDetailModal');$('receiptContent').innerHTML=receiptHTML(lastReceipt,false);showReceiptButtons(false);openModal('receiptModal');notifyUser('Sale completed',`Sale ${s?.receipt||''} completed and stock deducted.`,'info')}
async function rejectCurrentSale(){if(lastReceipt?.id)await rejectPendingSale(lastReceipt.id)}
async function rejectPendingSale(id){if(!confirm('Reject this pending sale? Stock will not be deducted.'))return;const r=await sb.rpc('reject_pending_sale',{p_sale_id:id});if(r.error)return alert(r.error.message);await loadData();closeModal('receiptModal')}

function printReceipt(){const html=$('receiptContent').innerHTML,w=window.open('','_blank','width=520,height=760');if(!w)return alert('Allow pop-ups to print the receipt.');w.document.write(`<html><head><title>Receipt</title><style>body{font-family:Arial,sans-serif;padding:20px}.receiptPreview{max-width:380px;margin:auto}.receiptPreview h2,.receiptPreview h3{text-align:center}.receiptMeta{text-align:center;font-size:11px;color:#555}.receiptTable{width:100%;border-collapse:collapse;margin-top:12px}.receiptTable th,.receiptTable td{font-size:11px;padding:6px;border-bottom:1px solid #ddd;text-align:left}.receiptTotal{text-align:right;border-top:1px dashed #777;margin-top:8px;padding-top:8px;font-weight:bold}.mutedItalic{font-size:11px;font-style:italic;text-transform:lowercase;color:#666}@media print{button{display:none}}</style></head><body>${html}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),300)}
$('saleForm').onsubmit=async e=>{e.preventDefault();if(!confirm('Save this sale as pending? Stock will NOT be deducted until you revisit the sale and click Complete Sale.'))return;try{const saved=await createPendingSale();await loadData();const s=sales.find(x=>x.id===saved.sale_id),items=saleItems.filter(x=>x.sale_id===saved.sale_id);lastReceipt={...s,date:s?.created_at||new Date(),items};closeModal('saleModal');$('receiptContent').innerHTML=receiptHTML(lastReceipt,true);showReceiptButtons(true);openModal('receiptModal')}catch(e){alert(e.message)}};
async function showStoredReceipt(id){const s=sales.find(x=>x.id===id);if(!s)return;const items=saleItems.filter(x=>x.sale_id===id);lastReceipt={...s,date:s.created_at,items};$('receiptContent').innerHTML=receiptHTML(lastReceipt,s.status!=='completed');showReceiptButtons(s.status==='pending');openModal('receiptModal')}
function showWholesale(name){const ss=sales.filter(s=>s.sale_type==='wholesale'&&s.business_name===name&&s.status==='completed'),items=saleItems.filter(i=>ss.some(s=>s.id===i.sale_id));$('wholesaleTitle').textContent=name;let total=0,profit=0;ss.forEach(s=>{total+=Number(s.total);profit+=Number(s.profit)});$('wholesaleContent').innerHTML=`<div class="stats"><div class="card"><div class="statLabel">Sales</div><div class="stat">${ss.length}</div></div><div class="card"><div class="statLabel">Income</div><div class="stat">${money(total)}</div></div><div class="card"><div class="statLabel">Profit</div><div class="stat">${money(profit)}</div></div></div><div class="card" style="margin-top:14px"><div class="tableWrap"><table><thead><tr><th>Date</th><th>Receipt</th><th>Items</th><th>Total</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${standardTime(s.created_at)}</td><td>${esc(s.receipt)}</td><td>${items.filter(i=>i.sale_id===s.id).map(i=>esc(drugLabel({name:i.product_name,brand_name:i.brand_name}))+' × '+i.qty).join(', ')}</td><td>${money(s.total)}</td></tr>`).join('')}</tbody></table></div></div>`;openModal('wholesaleModal')}
$('purchaseForm').onsubmit=async e=>{e.preventDefault();if(!confirm('Are you sure you want to record this purchase?'))return;const file=$('purchaseInvoice').files[0];let url=null,name=null;if(file){name=file.name;const path=`${profile.pharmacy_id}/purchase-invoices/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await sb.storage.from('pharmaplus-files').upload(path,file,{upsert:false});if(up.error)return alert('Invoice upload failed: '+up.error.message);url=sb.storage.from('pharmaplus-files').getPublicUrl(path).data.publicUrl}const r=await sb.from('purchases').insert({supplier_name:$('purchaseSupplierName').value.trim(),amount:+$('purchaseAmount').value,purchase_date:$('purchaseDate').value,invoice_url:url,invoice_name:name,pharmacy_id:profile.pharmacy_id});if(r.error)return alert(r.error.message);e.target.reset();$('purchaseDate').value=new Date().toISOString().slice(0,10);closeModal('purchaseModal');await loadData()};function renderPurchases(){$('purchaseRows').innerHTML=purchases.map(p=>`<tr><td>${p.purchase_date}</td><td>${esc(p.supplier_name)}</td><td>${money(p.amount)}</td><td>${p.invoice_url?`<a href="${esc(p.invoice_url)}" target="_blank">View invoice</a>`:'—'}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No purchases recorded.</td></tr>'}
function renderReportsBase(){const from=$('reportFrom').value,to=$('reportTo').value;if(from&&to)buildReportData();renderReportTiles()}
function onlineOrderCost(id){return onlineOrderItemsCache.filter(i=>i.order_id===id).reduce((a,i)=>a+Number(i.unit_buy||0)*Number(i.qty||0),0)}
function buildReportData(){const from=$('reportFrom').value,to=$('reportTo').value;if(!from||!to)return null;const inRange=d=>dateOnly(d)>=from&&dateOnly(d)<=to;const completed=sales.filter(s=>s.status==='completed'&&inRange(s.created_at));const ps=purchases.filter(p=>p.purchase_date>=from&&p.purchase_date<=to);const exps=expenses.filter(e=>e.expense_date>=from&&e.expense_date<=to);const onlineCompleted=onlineOrders.filter(o=>['ready','out_for_delivery','delivered','confirmed','complete','completed'].includes(o.status)&&inRange(o.created_at)),onlineRevenue=onlineCompleted.reduce((a,o)=>a+Number(o.total),0),onlineProfit=onlineCompleted.reduce((a,o)=>a+Number(o.total)-onlineOrderCost(o.id),0),revenue=completed.reduce((a,s)=>a+Number(s.total),0)+onlineRevenue,grossProfit=completed.reduce((a,s)=>a+Number(s.profit),0)+onlineProfit,purchase=ps.reduce((a,p)=>a+Number(p.amount),0),expenseTotal=exps.reduce((a,e)=>a+Number(e.amount),0),netProfit=grossProfit-expenseTotal;const expired=products.filter(p=>!p.archived&&days(p.expiry)<0),expiring=products.filter(p=>!p.archived&&days(p.expiry)>=0&&days(p.expiry)<=90),outstock=products.filter(p=>!p.archived&&Number(p.qty)<=0),low=products.filter(p=>!p.archived&&Number(p.qty)>0&&Number(p.qty)<=10&&days(p.expiry)>=0);const topMap={};saleItems.filter(i=>completed.some(s=>s.id===i.sale_id)).forEach(i=>{const key=i.product_name+'|'+(i.brand_name||'');topMap[key]??={name:i.product_name,brand:i.brand_name||'',qty:0,income:0,profit:0};topMap[key].qty+=Number(i.qty);topMap[key].income+=Number(i.line_total);topMap[key].profit+=Number(i.line_profit)});const top=Object.values(topMap).sort((a,b)=>b.qty-a.qty);const stock=products.filter(p=>!p.archived);const wm={};completed.filter(s=>s.sale_type==='wholesale').forEach(s=>{const n=s.business_name||'Unnamed';wm[n]??={sales:0,income:0,profit:0,last:s.created_at};wm[n].sales++;wm[n].income+=Number(s.total);wm[n].profit+=Number(s.profit);if(s.created_at>wm[n].last)wm[n].last=s.created_at});const cm={};exps.forEach(e=>cm[e.category]=(cm[e.category]||0)+Number(e.amount));return{from,to,revenue,grossProfit,purchase,expenseTotal,netProfit,expired,expiring,outstock,low,top,stock,wholesale:Object.entries(wm),expenses:exps,expenseCategories:Object.entries(cm)}}
function previewNames(arr){return arr.slice(0,3).map(p=>typeof p==='string'?p:(p.name?drugLabel(p):p[0])).join(' • ')||'No records';}
function reportCard(title,count,sub,key,preview='',roles=''){return `<div class="card reportTile" ${roles?`data-roles="${roles}"`:''} onclick="openReportDetail('${key}')"><h3>${title}</h3><div class="reportCount">${count}</div><p class="mini">${esc(sub)}</p><div class="mini" style="margin-top:7px">${esc(preview)}</div></div>`}
function renderReportTiles(){const d=buildReportData();if(!d)return;$('financialTiles').innerHTML=reportCard('Generated Income',money(d.revenue),'Completed sales in selected period','income','Open individual sales','admin,manager')+reportCard('Gross Profit',money(d.grossProfit),'Profit from completed sales','grossProfit','Open individual sale profits','admin,manager')+reportCard('Purchases',money(d.purchase),'Purchase money recorded','purchases','Open purchase records','admin,manager')+reportCard('Expenses',money(d.expenseTotal),'Operating expenses','expenses',previewNames(d.expenses),'admin,manager')+reportCard('Net Profit',money(d.netProfit),'Gross profit minus expenses','netProfit','Open calculation','admin,manager');$('inventoryTiles').innerHTML=reportCard('Expired Medicines',d.expired.length,'Open the complete expired list','expired',previewNames(d.expired))+reportCard('Medicines About to Expire',d.expiring.length,'Open the complete expiry list','expiring',previewNames(d.expiring))+reportCard('Out of Stock',d.outstock.length,'Medicines with zero quantity','outstock',previewNames(d.outstock))+reportCard('Low Stock',d.low.length,'Medicines with 1–10 units','low',previewNames(d.low))+reportCard('Top Selling Medicines',d.top.length,'Open ranked sales performance','top',d.top.slice(0,3).map(x=>drugLabel({name:x.name,brand_name:x.brand})).join(' • '))+reportCard('Total Stock at Hand',d.stock.length,'Open full stock valuation list','stock',previewNames(d.stock));$('customerTiles').innerHTML=reportCard('Wholesale Businesses',d.wholesale.length,'Open wholesale business summary','wholesale',d.wholesale.slice(0,3).map(x=>x[0]).join(' • '))+reportCard('Online Customers',new Set(onlineOrders.map(o=>o.customer_id)).size,'Customers who have placed online orders','onlineCustomers',onlineOrders.slice(0,3).map(o=>o.customer_name||'Customer').join(' • '))}
function openReportCategory(cat){document.querySelectorAll('.reportView').forEach(x=>x.classList.remove('active'));const el=$(cat+'ReportView');if(el)el.classList.add('active');buildReportData();renderReportTiles();applyPermissions()}
function refreshReports(){buildReportData();renderReportTiles()}
function getReportRows(key){
 const d=buildReportData();
 if(!d)return {title:'Report',rows:[]};
 const inPeriod=s=>s.status==='completed'&&dateOnly(s.created_at)>=d.from&&dateOnly(s.created_at)<=d.to;
 const onlinePeriod=onlineOrders.filter(o=>['ready','out_for_delivery','delivered','confirmed','complete','completed'].includes(o.status)&&dateOnly(o.created_at)>=d.from&&dateOnly(o.created_at)<=d.to);
 if(key==='income') return {title:'Generated Income',rows:[['Date','Reference','Customer','Source','Total'],...sales.filter(inPeriod).map(s=>[dateOnly(s.created_at),s.receipt,s.sale_type==='wholesale'?s.business_name:'Walk-in','POS',money(s.total)]),...onlinePeriod.map(o=>[dateOnly(o.created_at),o.order_number,o.customer_name||'Customer','Online Order',money(o.total)])]};
 if(key==='grossProfit') return {title:'Gross Profit',rows:[['Date','Reference','Customer','Source','Profit'],...sales.filter(inPeriod).map(s=>[dateOnly(s.created_at),s.receipt,s.sale_type==='wholesale'?s.business_name:'Walk-in','POS',money(s.profit)]),...onlinePeriod.map(o=>[dateOnly(o.created_at),o.order_number,o.customer_name||'Customer','Online Order',money(Number(o.total)-onlineOrderCost(o.id))])]};
 if(key==='onlineCustomers') return {title:'Online Customers',rows:[['Customer','Phone','Orders','Income','Last order'],...Object.values(onlineOrders.reduce((m,o)=>{const k=o.customer_id;m[k]??={name:o.customer_name||'Customer',phone:o.phone||'',orders:0,income:0,last:o.created_at};m[k].orders++;if(['ready','out_for_delivery','delivered','confirmed','complete','completed'].includes(o.status))m[k].income+=Number(o.total);if(o.created_at>m[k].last)m[k].last=o.created_at;return m},{})).map(x=>[x.name,x.phone,x.orders,money(x.income),standardTime(x.last)])]};
 if(key==='purchases') return {title:'Purchases',rows:[['Date','Supplier','Amount'],...purchases.filter(p=>p.purchase_date>=d.from&&p.purchase_date<=d.to).map(p=>[p.purchase_date,p.supplier_name,money(p.amount)])]};
 if(key==='expenses') return {title:'Expenses',rows:[['Date','Description','Category','Amount'],...d.expenses.map(e=>[e.expense_date,e.description,e.category,money(e.amount)])]};
 if(key==='netProfit') return {title:'Net Profit',rows:[['Metric','Amount'],['Generated income',money(d.revenue)],['Gross profit',money(d.grossProfit)],['Expenses',money(d.expenseTotal)],['Net profit',money(d.netProfit)]]};
 if(key==='expired') return {title:'Expired Items',rows:[['Generic','Brand','Batch','Expiry','Qty'],...d.expired.map(p=>[p.name,p.brand_name||'',p.batch,p.expiry,p.qty])]};
 if(key==='expiring') return {title:'Items About to Expire',rows:[['Generic','Brand','Batch','Expiry','Days','Qty'],...d.expiring.map(p=>[p.name,p.brand_name||'',p.batch,p.expiry,days(p.expiry),p.qty])]};
 if(key==='outstock') return {title:'Out of Stock Items',rows:[['Generic','Brand','Category','Batch','Expiry','Qty'],...d.outstock.map(p=>[p.name,p.brand_name||'',p.category,p.batch,p.expiry,p.qty])]};
 if(key==='low') return {title:'Low Stock Items',rows:[['Generic','Brand','Batch','Qty','Expiry'],...d.low.map(p=>[p.name,p.brand_name||'',p.batch,p.qty,p.expiry])]};
 if(key==='top') return {title:'Top Selling Items',rows:[['Generic','Brand','Units','Income','Profit'],...d.top.map(x=>[x.name,x.brand,x.qty,money(x.income),money(x.profit)])]};
 if(key==='stock') return {title:'Total Stock at Hand',rows:[['Generic','Brand','Category','Batch','Expiry','Date entered','Qty','Buying value','Wholesale value','Retail value'],...d.stock.map(p=>[p.name,p.brand_name||'',p.category,p.batch,p.expiry,dateOnly(p.entered_date||p.created_at),p.qty,money(p.qty*p.buy),money(p.qty*(p.wholesale_price??p.sell)),money(p.qty*(p.retail_price??p.sell))])]};
 if(key==='wholesale') return {title:'Wholesale Businesses',rows:[['Business','Sales','Income','Profit','Last sale'],...d.wholesale.map(x=>[x[0],x[1].sales,money(x[1].income),money(x[1].profit),standardTime(x[1].last)])]};
 return {title:'Report',rows:[]};
}
function openReportDetail(key){const r=getReportRows(key);currentReport={key,rows:r.rows,title:r.title};$('reportDetailTitle').textContent=r.title;$('reportDetailSubtitle').textContent=`${$('reportFrom').value} to ${$('reportTo').value}`;const rows=r.rows;$('reportDetailBody').innerHTML=`<div class="tableWrap"><table><thead><tr>${rows.length?rows[0].map(x=>`<th>${esc(x)}</th>`).join(''):''}</tr></thead><tbody>${rows.slice(1).map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${rows[0]?.length||1}" class="empty">No records in this report.</td></tr>`}</tbody></table></div>`;openModal('reportDetailModal')}
function printCurrentReport(){const r=currentReport;if(!r.rows.length)return;const w=window.open('','_blank');if(!w)return alert('Allow pop-ups to print the report.');w.document.write(`<html><head><title>${esc(r.title)}</title><style>body{font-family:Arial;padding:25px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:7px;font-size:11px;text-align:left}h1{margin-bottom:4px}</style></head><body><h1>${esc(pharmacy.name)}</h1><p>${esc(r.title)} — ${$('reportFrom').value} to ${$('reportTo').value}</p><table><thead><tr>${r.rows[0].map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${r.rows.slice(1).map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function exportCurrentReport(fmt){const r=currentReport;if(!r.rows.length)return;if(fmt==='excel'){const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(r.rows),'Report');XLSX.writeFile(wb,`PharmaPlus-${r.key}-${$('reportFrom').value}-to-${$('reportTo').value}.xlsx`);return}const {jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4'});let y=16;doc.setFontSize(16);doc.text(pharmacy.name,14,y);y+=7;doc.setFontSize(9);doc.text(`${r.title} — ${$('reportFrom').value} to ${$('reportTo').value}`,14,y);y+=8;r.rows.forEach((row,i)=>{const txt=row.map(v=>String(v??'')).join(' | ');const parts=doc.splitTextToSize(txt,180);if(y+parts.length*5>285){doc.addPage();y=16}doc.setFontSize(8);doc.text(parts,14,y);y+=Math.max(6,parts.length*5)});doc.save(`PharmaPlus-${r.key}-${$('reportFrom').value}-to-${$('reportTo').value}.pdf`)}
async function renderStaff(){if(!profile)return;const r=await sb.from('profiles').select('id,email,full_name,role,active').eq('pharmacy_id',profile.pharmacy_id).order('created_at',{ascending:true});if(r.error)return;const rows=r.data||[];const can=['admin','manager'].includes(profile.role);$('staffRows').innerHTML=rows.map(x=>{const canEdit=can&&x.id!==profile.id&&(profile.role==='admin'||!['admin','manager'].includes(x.role));const roles=profile.role==='admin'?['staff','pharmacist','storekeeper','manager','admin']:['staff','pharmacist','storekeeper'];return `<tr><td>${esc(x.email||'')}</td><td>${esc(x.full_name||'')}</td><td>${esc(x.role)}</td><td>${canEdit?`<select onchange="changeRole('${x.id}',this.value)">${roles.map(v=>`<option value="${v}" ${v===x.role?'selected':''}>${v==='storekeeper'?'Inventory Officer':v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select>`:'—'}</td><td><span class="badge ${x.active?'ok':'bad'}">${x.active?'Active':'Inactive'}</span></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">No staff found.</td></tr>'}
function renderExpenses(){if(!['admin','manager'].includes(profile?.role))return;const total=expenses.reduce((a,e)=>a+Number(e.amount),0),m=new Date().toISOString().slice(0,7),month=expenses.filter(e=>String(e.expense_date).slice(0,7)===m).reduce((a,e)=>a+Number(e.amount),0);if($('expenseTotal'))$('expenseTotal').textContent=money(total);if($('expenseMonth'))$('expenseMonth').textContent=money(month);$('expenseRows').innerHTML=expenses.map(e=>`<tr><td>${e.expense_date}</td><td>${esc(e.description)}${e.category==='Others'&&e.other_description?`<div class="mini">${esc(e.other_description)}</div>`:''}</td><td>${esc(e.category)}</td><td>${money(e.amount)}</td><td>${e.document_url?`<a href="${esc(e.document_url)}" target="_blank">View document</a>`:'—'}</td><td><button class="btn secondary" onclick="openExpenseModal('${e.id}')">Edit</button><button class="btn danger" onclick="deleteExpense('${e.id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No expenses recorded.</td></tr>'}
function openExpenseModal(id=''){const e=expenses.find(x=>x.id===id);$('expenseId').value=e?.id||'';$('expenseDescription').value=e?.description||'';$('expenseCategory').value=e?.category||'Rent';$('expenseOtherDescription').value=e?.other_description||'';$('expenseAmount').value=e?.amount??'';$('expenseDate').value=e?.expense_date||new Date().toISOString().slice(0,10);$('expenseNotes').value=e?.notes||'';$('expenseDocument').value='';$('expenseModalTitle').textContent=e?'Edit Expense':'Add Expense';$('expenseOtherWrap').classList.toggle('hidden',$('expenseCategory').value!=='Others');openModal('expenseModal')}
$('expenseCategory').onchange=()=>{$('expenseOtherWrap').classList.toggle('hidden',$('expenseCategory').value!=='Others')}
$('expenseForm').onsubmit=async e=>{e.preventDefault();if(!confirm($('expenseId').value?'Are you sure you want to save these expense changes?':'Are you sure you want to add this expense?'))return;const id=$('expenseId').value,file=$('expenseDocument').files[0];let document_url=expenses.find(x=>x.id===id)?.document_url||null,document_name=expenses.find(x=>x.id===id)?.document_name||null;if(file){document_name=file.name;const path=`${profile.pharmacy_id}/expenses/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await sb.storage.from('pharmaplus-files').upload(path,file,{upsert:false});if(up.error)return alert('Expense document upload failed: '+up.error.message);document_url=sb.storage.from('pharmaplus-files').getPublicUrl(path).data.publicUrl}const row={description:$('expenseDescription').value.trim(),category:$('expenseCategory').value,other_description:$('expenseCategory').value==='Others'?$('expenseOtherDescription').value.trim():null,amount:+$('expenseAmount').value,expense_date:$('expenseDate').value,notes:$('expenseNotes').value.trim()||null,document_url,document_name,pharmacy_id:profile.pharmacy_id,created_by:currentUser.id};const r=id?await sb.from('expenses').update(row).eq('id',id).eq('pharmacy_id',profile.pharmacy_id):await sb.from('expenses').insert(row);if(r.error)return alert(r.error.message);closeModal('expenseModal');await loadData()}
async function deleteExpense(id){if(!['admin','manager'].includes(profile?.role))return;if(!confirm('Delete this expense?'))return;const r=await sb.from('expenses').delete().eq('id',id).eq('pharmacy_id',profile.pharmacy_id);if(r.error)return alert(r.error.message);await loadData()}
$('settingsForm').onsubmit=async e=>{e.preventDefault();if(!confirm('Are you sure you want to save all pharmacy business settings?'))return;let logo=pharmacy.logo_url||null;const file=$('setLogo').files[0];if(file){const path=`${profile.pharmacy_id}/logo-${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await sb.storage.from('pharmaplus-files').upload(path,file,{upsert:true});if(up.error)return alert('Logo upload failed: '+up.error.message);logo=sb.storage.from('pharmaplus-files').getPublicUrl(path).data.publicUrl}const row={name:$('setName').value.trim(),contact:$('setContact').value.trim(),location:$('setLocation').value.trim(),email:$('setEmail').value.trim(),currency:$('setCurrency').value.trim()||'USh',logo_url:logo,mtn_number:$('setMtnNumber').value.trim()||null,mtn_merchant_code:$('setMtnCode').value.trim()||null,mtn_registration_name:$('setMtnName').value.trim()||null,airtel_number:$('setAirtelNumber').value.trim()||null,airtel_merchant_code:$('setAirtelCode').value.trim()||null,airtel_registration_name:$('setAirtelName').value.trim()||null,pickup_latitude:$('setPickupLat').value.trim()?Number($('setPickupLat').value):null,pickup_longitude:$('setPickupLng').value.trim()?Number($('setPickupLng').value):null,delivery_fee_per_km:Number($('setDeliveryFee').value||0)};if((row.pickup_latitude==null)!=(row.pickup_longitude==null))return alert('Enter both facility latitude and longitude, or use Current Location.');const r=await sb.from('pharmacies').update(row).eq('id',profile.pharmacy_id);if(r.error)return alert('Could not save settings: '+r.error.message);pharmacy={...pharmacy,...row};settings={...settings,...row};renderProfile();alert('Business settings saved. The Customer Portal will use the updated payment accounts, facility location and delivery fee.');};
async function captureFacilityLocation(){if(!navigator.geolocation)return alert('Location is not supported by this browser.');navigator.geolocation.getCurrentPosition(pos=>{$('setPickupLat').value=pos.coords.latitude.toFixed(7);$('setPickupLng').value=pos.coords.longitude.toFixed(7);alert('Facility location captured. Save the settings to keep it.')},err=>alert('Could not capture facility location: '+err.message),{enableHighAccuracy:true,timeout:15000,maximumAge:0})}

async function createStaffInvite(){if(!confirm('Generate this staff invitation?'))return;if(!['admin','manager'].includes(profile?.role))return alert('Only an Admin or Manager can create staff invitations.');const role=$('inviteRole').value;const allowed=profile.role==='admin'?['pharmacist','storekeeper','staff','manager','admin']:['pharmacist','storekeeper','staff'];if(!allowed.includes(role))return alert('You are not allowed to invite this role.');const days=Number($('inviteDays').value||7);const code='PP-'+crypto.randomUUID().replace(/-/g,'').slice(0,8).toUpperCase();const expires=new Date(Date.now()+days*86400000).toISOString();const r=await sb.from('staff_invites').insert({pharmacy_id:profile.pharmacy_id,code,role,expires_at:expires,created_by:currentUser.id});if(r.error)return alert(r.error.message);$('inviteResult').classList.remove('hidden');$('inviteResult').innerHTML=`<b>Invitation code:</b> <strong style="font-size:20px;letter-spacing:2px">${code}</strong><br>Role: ${role==='storekeeper'?'Inventory Officer':role[0].toUpperCase()+role.slice(1)}<br>Expires: ${standardTime(expires)}<br><span class="mini">Give this code to the employee during registration.</span>`;}
async function changeRole(id,role){if(id===profile.id)return;const allowed=profile.role==='admin'?['staff','pharmacist','storekeeper','manager','admin']:['staff','pharmacist','storekeeper'];if(!allowed.includes(role))return alert('You are not allowed to assign this role.');const r=await sb.from('profiles').update({role}).eq('id',id).eq('pharmacy_id',profile.pharmacy_id);if(r.error)alert(r.error.message);else await renderStaff()}
$('invFilter').addEventListener('change',renderInventory);$('reportFrom').value=new Date(Date.now()-29*86400000).toISOString().slice(0,10);$('reportTo').value=new Date().toISOString().slice(0,10);$('purchaseDate').value=new Date().toISOString().slice(0,10);(async()=>{if(cfg())await boot()})();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').catch(()=>{});}
